let catalog={books:[],source:{name:'墨格原创示例'}},books=[],downloads=[],queue=[],prefs={theme:'light',checkMinutes:30,autoDownload:true,direction:'ltr'},meta={},view='library',filter='all',query='',sort='recent',searchOpen=false,checking=false,reader=null,installPrompt=null,timer,toastTimer,detailId=null,importing=false,started=false,composing=false;
const objectUrls=new Map();
const coverURL=b=>{const blob=b.cover instanceof Blob?b.cover:downloads.find(d=>d.bookId===b.id&&d.coverBlob instanceof Blob)?.coverBlob;if(blob){if(!objectUrls.has(b.id))objectUrls.set(b.id,URL.createObjectURL(blob));return objectUrls.get(b.id);}return b.cover;};
