function updateNav(){const active=queue.filter(q=>q.status==='pending'||q.status==='loading').length;const news=books.filter(b=>b.following).reduce((n,b)=>n+(b.newChapterIds?.length||0),0);const content=nav.map(([id,ico,short,long])=>{const count=id==='updates'?news:id==='downloads'?active:0;return `<a class="nav-item ${view===id?'active':''}" href="#${id}" ${view===id?'aria-current="page"':''}>${icon(ico)}<span class="nav-desktop-label">${long}</span>${count?`<span class="nav-badge">${count}</span>`:''}</a>`;}).join('');$('#desktop-nav').innerHTML=content;$('#mobile-nav').innerHTML=nav.map(([id,ico,short])=>`<a class="nav-item ${view===id?'active':''}" href="#${id}" ${view===id?'aria-current="page"':''}>${icon(ico)}<span>${short}</span>${id==='updates'&&news?`<span class="nav-badge">${news}</span>`:id==='downloads'&&active?`<span class="nav-badge">${active}</span>`:''}</a>`).join('');$('#breadcrumb').innerHTML=`${nav.find(n=>n[0]===view)?.[3]||'我的书库'} <span>/ 每一格，都值得收藏</span>`;$('#search-toggle').innerHTML=icon(searchOpen?'close':'search');}
function heading(en,title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
