function searchBox(){return searchOpen||view==='discover'?`<div class="search-box">${icon('search')}<input id="search-input" type="search" placeholder="搜索书名、作者或标签" value="${esc(query)}" autocomplete="off" aria-label="搜索漫画">${query?`<button class="icon-button" data-action="clear-search" aria-label="清空搜索">${icon('close')}</button>`:''}</div>`:'';}
function matches(b){const q=query.trim().toLocaleLowerCase();return !q||[b.title,b.author,...(b.tags||[])].some(s=>String(s).toLocaleLowerCase().includes(q));}
