function card(b){const saved=isSaved(b.id),offline=downloads.some(d=>d.bookId===b.id),progress=bookProgress(b),badge=b.local?'本地导入':offline?'已离线':b.following?'追更中':'原创示例';return `<article class="book-card"><button class="book-cover-button" data-action="detail" data-id="${esc(b.id)}" aria-label="查看${esc(b.title)}"><img src="${esc(coverURL(b))}" alt="${esc(b.title)}封面" loading="lazy" width="300" height="400"><span class="cover-badge ${offline?'dark':''}">${badge}</span><span class="cover-bottom"><span>${b.chapters.length} 话 · ${b.chapters.reduce((n,c)=>n+c.pages.length,0)} 页</span>${icon('book')}</span></button><div class="book-info"><h3>${esc(b.title)}</h3><p>${esc(b.author)} <span>· ${(b.tags||[]).slice(0,2).map(esc).join(' / ')}</span></p>${progress?`<div class="book-progress"><span style="width:${progress}%"></span></div>`:''}<div class="book-row-actions"><span>${progress?`已读 ${progress}%`:'等待翻开的故事'}</span><button class="bookmark-btn ${saved?'saved':''}" data-action="save" data-id="${esc(b.id)}" aria-label="${saved?'移出书库':'加入书库'} ${esc(b.title)}" aria-pressed="${saved}">${icon(saved?'check':'plus')}</button></div></div></article>`;}
