function stats(){return `<div class="reading-stats">${[['book',books.length,'部','我的收藏'],['refresh',books.filter(b=>b.following).length,'部','正在追更'],['download',downloads.length,'话','离线保存'],['clock',books.filter(b=>b.read).length,'部','读过的故事']].map(([i,n,u,l])=>`<div class="stat"><span class="stat-icon">${icon(i)}</span><div><div class="stat-number">${n}<small>${u}</small></div><div class="stat-label">${l}</div></div></div>`).join('')}</div>`;}
function library(){let items=books.filter(b=>filter==='all'||filter==='following'&&b.following||filter==='downloaded'&&downloads.some(d=>d.bookId===b.id)||filter==='local'&&b.local).filter(matches);return heading('MY COLLECTION','我的书库','收藏一点喜欢，留一段时间给自己。',btn('import','导入漫画','plus'))+searchBox()+(!searchOpen?hero()+stats():'')+`<div class="section-toolbar"><div class="filter-tabs" role="tablist" aria-label="书库筛选">${[['all','全部漫画',books.length],['following','追更中',books.filter(b=>b.following).length],['downloaded','已离线',books.filter(b=>downloads.some(d=>d.bookId===b.id)).length],['local','本地',books.filter(b=>b.local).length]].map(([k,l,n])=>`<button class="filter-tab ${filter===k?'active':''}" role="tab" aria-selected="${filter===k}" data-action="filter" data-filter="${k}">${l}<small>${n}</small></button>`).join('')}</div><select id="sort-select" class="sort-select" aria-label="排序方式"><option value="recent" ${sort==='recent'?'selected':''}>最近阅读 ↓</option><option value="title" ${sort==='title'?'selected':''}>书名排序 ↓</option></select></div><div class="book-grid">${items.length?sorted(items).map(card).join(''):empty('book',query?'没有找到这本漫画':'书架留出了新的位置',query?'试试其他标题、作者或标签。':'导入已有漫画，或去发现页收藏一个原创故事。',btn(query?'clear-search':'discover',query?'清空搜索':'发现故事','compass','primary'))}</div><div class="source-note"><span>${icon('info')}示例漫画由墨格原创；导入内容仅保存在当前设备。</span><button class="text-button" data-action="help">了解书库 →</button></div>`;}
