function downloadsView(){const active=queue.filter(q=>['pending','loading','error'].includes(q.status));const items=downloads.filter(d=>!query||`${d.title} ${d.chapterTitle}`.includes(query));return heading('ALWAYS WITH YOU','离线下载','把故事装进口袋，没网络也能翻开。',btn('import','导入漫画','plus'))+searchBox()+`<div class="notice">${icon('device')}<div><h3>保存在当前设备的浏览器内</h3><p>离线保存包含完整漫画页。也可以导出 CBZ 到手机文件，便于备份或使用其他阅读器。</p></div></div>${active.length?`<div class="subheading"><h2>下载队列</h2><span>${active.length} 个任务</span></div><div class="list-stack">${active.map(q=>`<div class="download-row"><span class="stat-icon">${icon(q.status==='error'?'info':'download',q.status==='loading'?'spinner':'')}</span><div class="row-copy"><h3>${esc(q.title)}</h3><p>${q.status==='error'?esc(q.error):q.status==='pending'?'等待下载':`正在保存 ${q.progress}%`}</p>${q.status!=='error'?`<div class="download-progress"><span style="width:${q.progress}%"></span></div>`:''}</div>${q.status==='error'?btn('retry','重试','refresh','outline',`data-id="${esc(q.id)}"`):''}</div>`).join('')}</div>`:''}<div class="subheading"><h2>已离线保存</h2><span>${downloads.length} 话 · ${fmtBytes(downloads.reduce((n,d)=>n+d.size,0))}</span></div><div class="list-stack">${items.length?items.map(d=>{const b=findBook(d.bookId);return `<article class="download-row">${b?`<img class="row-cover" src="${esc(coverURL(b))}" alt="">`:icon('book')}<div class="row-copy"><h3>${esc(d.title)}</h3><p>${esc(d.chapterTitle)} · ${fmtBytes(d.size)}</p><p><span class="status-dot"></span>可离线阅读</p></div><div class="row-action"><button class="icon-button" data-action="read" data-id="${esc(d.bookId)}" data-chapter="${esc(d.chapterId)}" aria-label="阅读${esc(d.title)}">${icon('book')}</button><button class="icon-button" data-action="export-download" data-id="${esc(d.id)}" aria-label="导出CBZ">${icon('download')}</button><button class="icon-button" data-action="delete-download" data-id="${esc(d.id)}" aria-label="移除离线文件">${icon('trash')}</button></div></article>`;}).join(''):empty('download',query?'没有匹配的离线漫画':'下一次出发，带上故事','打开漫画详情，点击章节旁的下载按钮，即可保存到当前设备。',btn('discover','选择一本漫画','compass','primary'))}</div>`;}
function profile(){return heading('YOUR LITTLE CORNER','我的空间','一些阅读习惯，一点自己的小天地。')+`<div class="profile-banner"><div class="profile-avatar">M</div><div><h2>故事收藏家</h2><p>${books.length} 部收藏 · ${books.filter(b=>b.local).length} 部本地漫画 · ${books.filter(b=>b.read).length} 部已开始阅读</p></div><span>EVERY FRAME MATTERS</span></div><div class="settings-grid"><section class="settings-card"><h2>阅读偏好</h2><div class="setting-row"><div><strong>界面外观</strong><p>选一种舒服的阅读氛围</p></div><select id="theme-select" aria-label="界面外观">${[['light','浅色纸张'],['dark','深色夜读'],['system','跟随系统']].map(([v,l])=>`<option value="${v}" ${prefs.theme===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="setting-row"><div><strong>阅读方向</strong><p>日漫从右往左翻页，国漫从左往右</p></div><select id="direction-select" aria-label="阅读方向"><option value="ltr" ${prefs.direction!=='rtl'?'selected':''}>左 → 右</option><option value="rtl" ${prefs.direction==='rtl'?'selected':''}>右 → 左</option></select></div><div class="setting-row"><div><strong>追更检查间隔</strong><p>仅在网页打开且可见时生效</p></div><select id="interval-select" aria-label="追更检查间隔">${[[15,'每 15 分钟'],[30,'每 30 分钟'],[60,'每 1 小时'],[0,'手动检查']].map(([v,l])=>`<option value="${v}" ${Number(prefs.checkMinutes)===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="setting-row"><div><strong>新章节自动离线保存</strong><p>网页打开期间，发现更新后自动下载</p></div><input id="auto-download-toggle" type="checkbox" aria-label="新章节自动离线保存" ${prefs.autoDownload?'checked':''} style="width:19px;height:19px;accent-color:var(--green)"></div><div class="setting-row"><div><strong>添加到主屏幕</strong><p>像打开 App 一样打开书库</p></div><button class="icon-button" data-action="install" aria-label="添加到主屏幕">${icon('plus')}</button></div></section><section class="settings-card"><h2>我的文件</h2><div class="setting-row"><div><strong>导入漫画</strong><p>支持 CBZ 或多张 JPG / PNG / WebP 图片</p></div><button class="icon-button" data-action="import" aria-label="导入漫画">${icon('folder')}</button></div><div class="setting-row"><div><strong>导出书目与进度</strong><p>JSON 备份，不包含导入的图片文件</p></div><button class="icon-button" data-action="export-backup" aria-label="导出书目与进度">${icon('download')}</button></div><div class="setting-row"><div><strong>恢复书目与进度</strong><p>导入墨格导出的 JSON 备份</p></div><button class="icon-button" data-action="restore-backup" aria-label="恢复书目与进度">${icon('refresh')}</button></div></section><section class="settings-card"><h2>设备存储</h2><div id="storage-info"><p class="footnote">正在读取存储用量…</p></div><div class="setting-row"><div><strong>申请持久保存</strong><p>减少浏览器自动回收本地文件的可能</p></div>${btn('persist','申请保存',null)}</div><div class="setting-row"><div><strong>清空本地数据</strong><p>移除书库、进度和所有离线文件</p></div>${btn('clear-data','清空',null,'outline')}</div></section><section class="settings-card"><h2>关于墨格</h2><div class="setting-row"><div><strong>墨格 · 随身漫画书库</strong><p>版本 1.0 / 手机网页应用</p></div><img src="/icon.svg" width="34" height="34" alt="墨格"></div><div class="setting-row"><div><strong>当前内容源</strong><p>墨格原创示例 · CC0 自由使用</p></div><button class="icon-button" data-action="source-info" aria-label="内容源说明">${icon('info')}</button></div><p class="footnote">书库保存在当前浏览器，不会跨设备自动同步。请保留原始漫画文件；清除浏览器数据会移除本地书库。</p></section></div>`;}
function render(){if(!started)return;updateNav();const focused=document.activeElement?.id==='search-input';const pos=focused?document.activeElement.selectionStart:null;$('#main').innerHTML=(!navigator.onLine?'<div class="offline-banner">当前离线，可阅读已经导入或保存的漫画。</div>':'')+({library,discover,updates,downloads:downloadsView,profile}[view]||library)();if(focused){const el=$('#search-input');el?.focus();try{el?.setSelectionRange(pos,pos);}catch{}}if(view==='profile')renderStorage();}
async function renderStorage(){try{const s=await storageEstimate();const el=$('#storage-info');if(!el)return;el.innerHTML=`<p class="footnote">${s.usage==null?'当前浏览器不提供用量统计':`已使用 <strong>${fmtBytes(s.usage)}</strong>${s.quota?' / 可用配额 '+fmtBytes(s.quota):''}`}</p><div class="storage-track"><span style="width:${s.quota?Math.min(100,s.usage/s.quota*100):0}%"></span></div><p class="footnote">${s.persistent?'已获持久存储权限':'当前采用浏览器默认存储策略'}</p>`;}catch{const el=$('#storage-info');if(el)el.textContent='当前浏览器无法读取存储统计。';}}
async function saveMeta(){await putItem('settings',{id:'state',...meta});}
async function saveBook(b){await putItem('books',b);const idx=books.findIndex(x=>x.id===b.id);if(idx===-1)books.push(b);else books[idx]=b;}
async function addBook(b){if(isSaved(b.id))return findBook(b.id);const item={...b,createdAt:Date.now(),following:false,knownChapterIds:b.chapters.map(c=>c.id),newChapterIds:[]};await saveBook(item);return item;}
async function toggleSaved(id){const b=findBook(id);if(!b)return;if(isSaved(id)){if(b.local&&!confirm('移出书库会删除这部本地导入的漫画和阅读进度。确定移除吗？'))return;for(const q of queue.filter(q=>q.bookId===id)){q.cancelled=true;q.status='cancelled';}for(const d of downloads.filter(d=>d.bookId===id))await deleteItem('downloads',d.id);downloads=downloads.filter(d=>d.bookId!==id);await deleteItem('books',id);books=books.filter(x=>x.id!==id);if(objectUrls.has(id)){URL.revokeObjectURL(objectUrls.get(id));objectUrls.delete(id);}toast('已移出书库');}else{await addBook(b);toast('已加入书库');}render();if(detailId===id){if(findBook(id))showDetail(id,true);else $('#detail-dialog').close();}}
async function toggleFollow(id){let b=findBook(id);if(!b||b.local)return;b=await addBook(b);b.following=!b.following;if(!b.following)b.newChapterIds=[];if(b.following)b.knownChapterIds=b.chapters.map(c=>c.id);await saveBook(b);toast(b.following?'已开启追更，打开网页时会检查更新':'已取消追更');render();if(detailId===id)showDetail(id,true);}
function showDetail(id,refresh=false){const b=findBook(id);if(!b)return;detailId=id;const saved=isSaved(id);const d=$('#detail-dialog');d.innerHTML=`<div class="dialog-topline"><span>${b.local?'LOCAL COLLECTION':'ORIGINAL SHORT STORIES'}</span><button class="icon-button" data-action="close-detail" aria-label="关闭详情">${icon('close')}</button></div><div class="detail-overview"><img src="${esc(coverURL(b))}" alt="${esc(b.title)}封面"><div class="detail-copy"><h2>${esc(b.title)}</h2><span class="muted" style="font-size:11px">${esc(b.author)}</span><div class="tags">${(b.tags||[]).map(t=>`<span class="pill">${esc(t)}</span>`).join('')}</div><p>${esc(b.description||'属于你自己的故事，随时翻开。')}</p></div></div><div class="detail-actions">${btn('read',b.read?'继续阅读':'开始阅读','book','primary',`data-id="${esc(id)}"`)}${btn('save',saved?'已在书库':'加入书库',saved?'check':'plus','outline',`data-id="${esc(id)}"`)}${!b.local?btn('follow',b.following?'追更中':'追更','bell',b.following?'quiet':'outline',`data-id="${esc(id)}"`):''}</div><div class="chapter-heading"><strong>章节目录</strong><small>共 ${b.chapters.length} 话${b.local?' · 本地文件':' · 原创示例'}</small></div><div class="chapter-list">${b.chapters.map(c=>{const done=chapterDownload(id,c.id),q=queue.find(q=>q.id===id+'::'+c.id&&q.status!=='done');return `<div class="chapter"><button data-action="read" data-id="${esc(id)}" data-chapter="${esc(c.id)}"><h3>${esc(c.title)}</h3><p>${c.pages.length} 页${c.publishedAt?' · '+c.publishedAt:''}${done?' · 已离线':b.local?' · 已在设备保存':''}</p></button>${!b.local?`<button class="icon-button" data-action="download" data-id="${esc(id)}" data-chapter="${esc(c.id)}" aria-label="${done?'导出CBZ':q?'查看下载':'离线下载'} ${esc(c.title)}">${icon(done?'check':q?'clock':'download')}</button>`:''}</div>`;}).join('')}</div>`;if(!refresh||!d.open)d.showModal();}
async function checkUpdates(silent=false){if(checking)return;if(!navigator.onLine){if(!silent)toast('当前离线，联网后再检查更新');return;}checking=true;if(view==='updates')render();try{const r=await fetch('/catalog.json?t='+Date.now(),{cache:'no-store'});if(!r.ok)throw new Error('内容源暂时不可用，请稍后重试。');const next=validateCatalog(await r.json());let added=0;for(const current of [...books]){if(current.local||!current.following)continue;const latest=next.books.find(b=>b.id===current.id);if(!latest)continue;const known=current.knownChapterIds||current.chapters.map(c=>c.id);const fresh=latest.chapters.filter(c=>!known.includes(c.id)).map(c=>c.id);added+=fresh.length;await saveBook({...current,...latest,following:true,createdAt:current.createdAt,read:current.read,lastRead:current.lastRead,knownChapterIds:latest.chapters.map(c=>c.id),newChapterIds:[...new Set([...(current.newChapterIds||[]),...fresh])],checkedAt:Date.now()});if(prefs.autoDownload)for(const chapterId of fresh)await enqueueDownload(current.id,chapterId,true);}catalog=next;meta.lastCheck=Date.now();meta.catalog=catalog;await saveMeta();if(!silent)toast(added?`发现 ${added} 话新章节`:'检查完成，暂无新章节');}catch(e){if(!silent)toast(errorText(e));}finally{checking=false;render();}}
function validateCatalog(data){if(!data||!Array.isArray(data.books)||data.source?.id!=='moge-original')throw new Error('原创内容目录格式无效。');for(const b of data.books){if(!/^[a-z0-9-]+$/.test(b.id)||typeof b.title!=='string'||!Array.isArray(b.chapters)||!b.cover?.startsWith('/assets/'))throw new Error('漫画目录不完整。');for(const c of b.chapters){if(!Array.isArray(c.pages)||!c.pages.length||!c.pages.every(p=>typeof p==='string'&&p.startsWith('/assets/'))||!c.download?.startsWith('/assets/'))throw new Error('漫画章节地址无效。');}}return data;}
async function enqueueDownload(id,chapterId,silent=false){let b=findBook(id);const c=b?.chapters.find(c=>c.id===chapterId);if(!c||b.local)return;const done=chapterDownload(id,chapterId);if(done){saveBlob(done.archive,done.filename);toast('正在导出 CBZ 到手机文件');return;}const taskId=id+'::'+chapterId;if(queue.some(q=>q.id===taskId&&['pending','loading'].includes(q.status))){toast('已在下载队列中');return;}b=await addBook(b);queue=queue.filter(q=>q.id!==taskId);queue.push({id:taskId,bookId:id,chapterId,title:b.title+' · '+c.title,status:'pending',progress:0});if(!silent)toast('已加入下载队列');render();if(detailId===id)showDetail(id,true);pumpQueue();}
let pumping=false;
async function pumpQueue(){if(pumping)return;pumping=true;try{while(queue.some(q=>q.status==='pending')){const q=queue.find(q=>q.status==='pending');q.status='loading';const b=findBook(q.bookId),c=b?.chapters.find(c=>c.id===q.chapterId);try{if(!c)throw new Error('找不到漫画章节。');const pages=[];for(let i=0;i<c.pages.length;i++){if(q.cancelled)throw new Error('下载已取消');const r=await fetch(c.pages[i]);if(!r.ok)throw new Error('页面下载失败，请联网后重试。');const blob=await r.blob();if(blob.size>30*1024*1024)throw new Error('单页文件过大。');pages.push(blob);q.progress=Math.round((i+1)/(c.pages.length+1)*100);if(view==='downloads')render();}const r=await fetch(c.download);if(!r.ok)throw new Error('CBZ 文件下载失败。');const archive=await r.blob();let coverBlob;try{const coverResponse=await fetch(b.cover);if(coverResponse.ok)coverBlob=await coverResponse.blob();}catch{}const item={coverBlob,id:q.id,bookId:b.id,chapterId:c.id,title:b.title,chapterTitle:c.title,pages,archive,filename:b.title+'-'+c.title+'.cbz',size:archive.size+pages.reduce((n,p)=>n+p.size,0)+(coverBlob?.size||0),createdAt:Date.now()};if(q.cancelled||!isSaved(q.bookId))throw new Error('下载已取消');await putItem('downloads',item);if(q.cancelled||!isSaved(q.bookId)){await deleteItem('downloads',item.id);throw new Error('下载已取消');}downloads=downloads.filter(d=>d.id!==item.id);downloads.push(item);q.status='done';q.progress=100;toast(`${b.title} 已离线保存`);}catch(e){if(q.cancelled){q.status='cancelled';}else{q.status='error';q.error=errorText(e);toast(q.error);}}render();if(detailId===q.bookId&&$('#detail-dialog').open)showDetail(q.bookId,true);}}finally{pumping=false;}}
function saveBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.rel='noopener';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);}
async function openReader(id,chapterId){let b=findBook(id);if(!b)return;b=await addBook(b);let c=b.chapters.find(c=>c.id===(chapterId||b.read?.chapterId))||b.chapters[0];if(!c)return;const page=chapterId?(b.read?.chapterId===chapterId?b.read.page:0):b.read?.page||0;const downloaded=chapterDownload(id,c.id);reader={book:b,chapter:c,pages:downloaded?.pages||c.pages,page:Math.min(page,c.pages.length-1),urls:[],fit:true,zoom:false};$('#detail-dialog').close();detailId=null;await markRead();renderReader();$('#reader-dialog').showModal();}
function renderReader(){if(!reader)return;const {book:b,chapter:c,pages,page,fit,zoom}=reader;
for(const url of reader.urls)URL.revokeObjectURL(url);reader.urls=[];
let src=pages[page];if(src instanceof Blob){src=URL.createObjectURL(src);reader.urls.push(src);}
const last=pages.length-1,d=$('#reader-dialog');
d.innerHTML=`<header class="reader-header"><button class="icon-button" data-action="close-reader" aria-label="退出阅读">${icon('back')}</button><div class="reader-title"><h2>${esc(b.title)}</h2><p>${esc(c.title)} · 第 ${page+1} / ${pages.length} 页</p></div><span class="pill">${b.local||chapterDownload(b.id,c.id)?'本地阅读':'在线阅读'}</span><button class="icon-button" data-action="reader-zoom" aria-label="${zoom?'还原页面':'放大页面'}" aria-pressed="${!!zoom}">${icon('search')}</button><button class="icon-button" data-action="reader-fit" aria-label="切换整页或适应宽度" aria-pressed="${fit}">${icon('expand')}</button></header><div class="reader-page ${fit&&!zoom?'fit-page':''} ${zoom?'zoomed':''}" id="reader-stage"><img id="reader-image" src="${esc(src)}" alt="${esc(b.title)}第 ${page+1} 页"><button class="reader-zone prev" data-zone="prev" aria-label="上一页"></button><button class="reader-zone next" data-zone="next" aria-label="下一页"></button></div><footer class="reader-bottom"><span class="reader-progress" style="width:${(page+1)/pages.length*100}%"></span><input id="reader-slider" class="reader-slider" type="range" min="0" max="${last}" value="${page}" aria-label="跳转到指定页"><div class="reader-controls">${btn('prev-page','上一页','back','outline',page===0?'disabled':'')}<span>${page+1} / ${pages.length}</span>${btn('next-page',page===last?'读完了':'下一页',page===last?'check':'arrow','outline')}</div></footer>`;
d.classList.toggle('zoomed',!!zoom);
$('#reader-image').onerror=()=>toast('页面暂时无法加载，请联网后重试，或先离线保存。');}
async function markRead(){if(!reader)return;const b=books.find(b=>b.id===reader.book.id)||reader.book;reader.book=b;b.read={chapterId:reader.chapter.id,page:reader.page};b.lastRead=Date.now();b.newChapterIds=(b.newChapterIds||[]).filter(id=>id!==reader.chapter.id);await saveBook(b);}
async function readerPage(delta){if(!reader)return;if(delta>0&&reader.page===reader.pages.length-1){const idx=reader.book.chapters.findIndex(c=>c.id===reader.chapter.id);if(idx<reader.book.chapters.length-1){const c=reader.book.chapters[idx+1];reader.chapter=c;reader.pages=chapterDownload(reader.book.id,c.id)?.pages||c.pages;reader.page=0;}else{$('#reader-dialog').close();toast('这一话读完了，期待下一个故事。');return;}}else reader.page=Math.max(0,Math.min(reader.pages.length-1,reader.page+delta));await markRead();renderReader();}
function readerGoTo(n){if(!reader)return;const last=reader.pages.length-1;reader.page=Math.max(0,Math.min(last,n));return markRead().then(renderReader).catch(err=>toast(errorText(err)));}
function readerZoom(){if(!reader)return;reader.zoom=!reader.zoom;if(reader.zoom)reader.fit=false;renderReader();}
function help(title,content){const d=$('#help-dialog');d.innerHTML=`<button class="icon-button" data-action="close-help" aria-label="关闭帮助">${icon('close')}</button><h2>${title}</h2>${content}${btn('close-help','知道了',null,'primary')}`;if(!d.open)d.showModal();}
async function importFiles(list){if(importing||!list.length)return;importing=true;toast('正在导入漫画，请稍候…');try{const files=[...list],archives=files.filter(f=>/\.cbz$/i.test(f.name)),images=files.filter(f=>!archives.includes(f));let count=0;for(const archive of archives){const b=await importComicFiles([archive]);books.push(b);count++;}if(images.length){const b=await importComicFiles(images);books.push(b);count++;}view='library';filter='local';location.hash='library';render();toast(`已导入 ${count} 部漫画，文件已保存在当前设备`);}catch(e){books=await getItems('books');render();toast(errorText(e));}finally{importing=false;$('#file-input').value='';}}
async function localSignature(b){if(!b.local)return undefined;const pages=b.chapters.flatMap(c=>c.pages);if(!(pages[0] instanceof Blob))return undefined;const digest=await crypto.subtle.digest('SHA-256',await pages[0].arrayBuffer());return pages.map(p=>p.size).join(',')+':'+Array.from(new Uint8Array(digest),n=>n.toString(16).padStart(2,'0')).join('');}
async function exportBackup(){const backup={format:'moge-reading-backup',version:1,exportedAt:new Date().toISOString(),preferences:prefs,books:await Promise.all(books.map(async b=>({id:b.id,title:b.title,local:!!b.local,localSignature:await localSignature(b),following:b.following||false,read:b.read,lastRead:b.lastRead,knownChapterIds:b.knownChapterIds})))};saveBlob(new Blob([JSON.stringify(backup,null,2)],{type:'application/json'}),'墨格书目与进度.json');toast('已导出书目与进度；不包含本地漫画文件');}
async function restoreBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files?.[0];if(!file)return;if(file.size>2*1024*1024)throw new Error('备份文件过大。');const data=JSON.parse(await file.text());if(data.format!=='moge-reading-backup'||data.version!==1||!Array.isArray(data.books)||data.books.length>1000)throw new Error('这不是有效的墨格书目备份。');let n=0,skipped=0;for(const entry of data.books){let current=findBook(entry.id);if(!current&&entry.local&&entry.localSignature){const matches=[];for(const candidate of books.filter(b=>b.local))if(await localSignature(candidate)===entry.localSignature)matches.push(candidate);if(matches.length===1)current=matches[0];}if(!current){skipped++;continue;}let b=await addBook(current);if(entry.read){const c=b.chapters.find(c=>c.id===entry.read.chapterId);if(c&&Number.isInteger(entry.read.page))b.read={chapterId:c.id,page:Math.min(Math.max(0,entry.read.page),c.pages.length-1)};}b.following=!b.local&&entry.following===true;if(Array.isArray(entry.knownChapterIds))b.knownChapterIds=entry.knownChapterIds.filter(id=>typeof id==='string').slice(0,10000);if(typeof entry.lastRead==='number'&&Number.isFinite(entry.lastRead))b.lastRead=entry.lastRead;await saveBook(b);n++;}if(data.preferences){if(typeof data.preferences.autoDownload==='boolean')prefs.autoDownload=data.preferences.autoDownload;if(['light','dark','system'].includes(data.preferences.theme))prefs.theme=data.preferences.theme;if([0,15,30,60].includes(data.preferences.checkMinutes))prefs.checkMinutes=data.preferences.checkMinutes;if(['ltr','rtl'].includes(data.preferences.direction))prefs.direction=data.preferences.direction;await putItem('settings',{id:'preferences',...prefs});applyTheme();configureTimer();}render();toast(`已恢复 ${n} 部漫画的书目与进度${skipped?'；'+skipped+' 部本地漫画需先重新导入':''}`);}catch(e){toast(errorText(e));}};input.click();}
async function install(){if(installPrompt){await installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;}else help('把墨格放到主屏幕','<p><strong>iPhone / iPad</strong><br>使用 Safari 打开此网页，点击分享按钮，选择“添加到主屏幕”。</p><p><strong>安卓手机</strong><br>使用 Chrome 打开此网页，在菜单中选择“安装应用”或“添加到主屏幕”。如果浏览器尚未提供安装入口，可以先收藏此网页。</p><p>第一次联网打开并保存漫画后，即可阅读设备内的离线内容。</p>');}
async function handleAction(action,el){const id=el?.dataset.id,chapter=el?.dataset.chapter;switch(action){case 'import':if(importing)toast('正在导入，请稍候');else $('#file-input').click();break;case 'search':if(view==='profile')location.hash='library';searchOpen=!searchOpen;query='';render();if(searchOpen)$('#search-input')?.focus();break;case 'clear-search':query='';render();$('#search-input')?.focus();break;case 'filter':filter=el.dataset.filter;render();break;case 'profile':location.hash='profile';break;case 'discover':location.hash='discover';break;case 'detail':showDetail(id);break;case 'close-detail':$('#detail-dialog').close();detailId=null;break;case 'save':await toggleSaved(id);break;case 'follow':await toggleFollow(id);break;case 'read':await openReader(id,chapter);break;case 'close-reader':$('#reader-dialog').close();break;case 'reader-fit':if(reader){reader.fit=!reader.fit;if(reader.fit)reader.zoom=false;renderReader();}break;case 'reader-zoom':readerZoom();break;case 'prev-page':await readerPage(-1);break;case 'next-page':await readerPage(1);break;case 'check':await checkUpdates();break;case 'download':await enqueueDownload(id,chapter);break;case 'retry':{const q=queue.find(q=>q.id===id);if(q){q.status='pending';q.progress=0;render();pumpQueue();}break;}case 'export-download':{const d=downloads.find(d=>d.id===id);if(d)saveBlob(d.archive,d.filename);break;}case 'delete-download':{if(!confirm('移除这话的离线文件？书库与阅读进度会保留。'))break;await deleteItem('downloads',id);downloads=downloads.filter(d=>d.id!==id);render();toast('已移除离线文件');break;}case 'help':help('你的随身漫画书库','<p>内置的原创示例可以阅读、收藏、追更和下载。点击漫画封面打开详情；章节旁的下载图标可将漫画保存到当前设备。</p><p>你也可以导入 CBZ 漫画压缩包，或一次选择多张图片组成一本漫画。图片按文件名自然排序，支持 JPG、PNG、WebP、GIF、AVIF。</p><p>本地书库不会跨设备同步。导出的书目备份只包含收藏和阅读进度，请另外保留原始漫画文件。</p>');break;case 'source-info':help('关于当前内容源','<p>当前接入的是<strong>墨格原创示例源</strong>，6 部原创短篇及页图采用 CC0 许可，可自由阅读、保存和下载。</p><p>检查更新会读取已发布的真实目录，并与设备上记录的章节比较。示例源只有在发布新内容时才会出现新章节。</p><p>本版本尚未连接外部漫画站点；可使用本地导入管理自己已有的漫画。</p>');break;case 'close-help':$('#help-dialog').close();break;case 'install':await install();break;case 'export-backup':await exportBackup();break;case 'restore-backup':await restoreBackup();break;case 'persist':{const granted=await navigator.storage?.persist?.();toast(granted?'已获得持久存储权限':'浏览器暂未授予权限，请保留原始文件备份');renderStorage();break;}case 'clear-data':{if(pumping||importing||checking){toast('请等待导入、下载或更新检查完成后再清空。');break;}if(!confirm('确定清空此设备的全部书库、阅读进度和离线文件？此操作无法撤销。'))break;await clearAll();for(const u of objectUrls.values())URL.revokeObjectURL(u);objectUrls.clear();if('caches'in window)for(const k of await caches.keys())if(k.startsWith('moge-shell-')){const cache=await caches.open(k);for(const req of await cache.keys())if(new URL(req.url).pathname.startsWith('/assets/'))await cache.delete(req);}books=[];downloads=[];queue=[];meta={initialized:true,catalog};prefs={theme:'light',checkMinutes:30,autoDownload:true,direction:'ltr'};await saveMeta();await putItem('settings',{id:'preferences',...prefs});applyTheme();configureTimer();render();toast('本地数据已清空');break;}}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)handleAction(el.dataset.action,el).catch(e=>toast(errorText(e)));});
document.addEventListener('compositionstart',e=>{if(e.target.id==='search-input')composing=true;});
document.addEventListener('compositionend',e=>{if(e.target.id==='search-input'){composing=false;query=e.target.value;render();}});
document.addEventListener('input',e=>{if(e.target.id==='search-input'&&!composing&&!e.isComposing){query=e.target.value;render();}});
document.addEventListener('change',async e=>{try{if(e.target.id==='sort-select'){sort=e.target.value;render();}if(e.target.id==='theme-select'||e.target.id==='interval-select'||e.target.id==='auto-download-toggle'){if(e.target.id==='theme-select')prefs.theme=e.target.value;else if(e.target.id==='interval-select')prefs.checkMinutes=Number(e.target.value);else prefs.autoDownload=e.target.checked;await putItem('settings',{id:'preferences',...prefs});applyTheme();configureTimer();toast('偏好已保存');}}catch(e){toast(errorText(e));}});
$('#file-input').addEventListener('change',e=>importFiles(e.target.files));
$('#detail-dialog').addEventListener('close',()=>{detailId=null;});
$('#reader-dialog').addEventListener('close',()=>{if(reader)for(const u of reader.urls)URL.revokeObjectURL(u);reader=null;render();});
document.addEventListener('keydown',e=>{if(!reader||$('#help-dialog').open)return;const forward=prefs.direction==='rtl'?-1:1;if(e.key==='ArrowRight'||e.key===' '||e.key==='PageDown'){e.preventDefault();readerPage(forward).catch(err=>toast(errorText(err)));}else if(e.key==='ArrowLeft'||e.key==='PageUp'){e.preventDefault();readerPage(-forward).catch(err=>toast(errorText(err)));}else if(e.key==='Home'){e.preventDefault();readerGoTo(0);}else if(e.key==='End'){e.preventDefault();readerGoTo(reader.pages.length-1);}else if(e.key==='+'||e.key==='='){e.preventDefault();readerZoom();}});
$('#reader-dialog').addEventListener('click',e=>{if(!reader)return;const zone=e.target.closest('[data-zone]');if(!zone)return;const forward=zone.dataset.zone==='next'?1:-1;readerPage(prefs.direction==='rtl'?-forward:forward).catch(err=>toast(errorText(err)));});
$('#reader-dialog').addEventListener('change',e=>{if(e.target.id!=='reader-slider'||!reader)return;readerGoTo(Number(e.target.value));});
document.addEventListener('change',async e=>{if(e.target.id!=='direction-select')return;prefs.direction=e.target.value==='rtl'?'rtl':'ltr';await putItem('settings',{id:'preferences',...prefs});toast('阅读方向：'+(prefs.direction==='rtl'?'右 → 左':'左 → 右'));});
let touchStart=null;$('#reader-dialog').addEventListener('touchstart',e=>{touchStart=e.touches.length===1?{x:e.touches[0].clientX,y:e.touches[0].clientY}:null;},{passive:true});$('#reader-dialog').addEventListener('touchend',e=>{if(!touchStart||!reader)return;const dx=e.changedTouches[0].clientX-touchStart.x,dy=e.changedTouches[0].clientY-touchStart.y;if(Math.abs(dx)>75&&Math.abs(dy)<70)readerPage(prefs.direction==='rtl'?(dx<0?-1:1):(dx<0?1:-1)).catch(err=>toast(errorText(err)));touchStart=null;},{passive:true});
window.addEventListener('hashchange',()=>{view=nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'library';query='';searchOpen=false;render();window.scrollTo(0,0);});
window.addEventListener('online',()=>{render();checkUpdates(true);});window.addEventListener('offline',render);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
matchMedia('(prefers-color-scheme:dark)').addEventListener?.('change',()=>{if(prefs.theme==='system')applyTheme();});
async function init(){try{await openStore();[books,downloads]=await Promise.all([getItems('books'),getItems('downloads')]);meta=await getItem('settings','state')||{};prefs={...prefs,...await getItem('settings','preferences')};applyTheme();try{const r=await fetch('/catalog.json',{cache:'no-store'});if(!r.ok)throw new Error('无法读取漫画目录');catalog=validateCatalog(await r.json());}catch(e){if(meta.catalog)catalog=validateCatalog(meta.catalog);else if(!books.length)throw e;}if(!meta.initialized){for(const b of catalog.books.slice(0,4)){await saveBook({...b,createdAt:Date.now(),following:['moon-post','forest-radio'].includes(b.id),knownChapterIds:b.chapters.map(c=>c.id),newChapterIds:[]});}meta.initialized=true;}meta.catalog=catalog;await saveMeta();view=nav.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'library';started=true;render();configureTimer();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});if(books.some(b=>b.following))checkUpdates(true);}catch(e){$('#main').innerHTML=empty('info','书库暂时无法打开',esc(errorText(e))+' 请确认浏览器允许本地存储，且首次打开时已联网。',btn('reload','重新打开','refresh','primary'));document.addEventListener('click',e=>{if(e.target.closest('[data-action="reload"]'))location.reload();});}}
init();
